    , PRGR_STAT_CD
    , CUST_ID
    , SVC_CNTR_NO
    , RSLT_CD
    , RSLT_MSG
    , RSLT_DT
    , NSTEP_GLOBAL_ID
    , PRDC_CHK_NOTI_MSG
    , NP_BCNTR_TYPE_CD
    , NP_FEE
    , NP_NCHRG_AMT
    , NP_PNLT_AMT
    , NP_UNPAY_AMT
