    , #{prgrStatCd}
    , #{custId}
    , #{svcCntrNo}
    , #{rsltCd}
    , #{rsltMsg}
    , TO_CHAR(SYSDATE,'YYYYMMDDHH24MISS')
    , #{nstepGlobalId}
    , #{prdcChkNotiMsg}
    , #{npBcntrTypeCd}
    , #{npFee}
    , #{npNchrgAmt}
    , #{npPnltAmt}
    , #{npUnpayAmt}
    , #{npHndstInstAmt}
    , #{npPrepayAmt}
    , #{npBaseChrgAmt}
    , #{npNtnlChrgAmt}
    , #{npIntlChrgAmt}
    , #{npAddChrgAmt}
    , #{npEtcChrgAmt}
    , #{npVat}
    , #{npRmnStrtDt}
    , #{npRmnEndDt}
    , #{tlphNoStatCd}
    , #{asgnAgncId}
    , #{tlphNoOwnCmpnCd}
    , #{openSvcIndCd}
    , #{encdTlphNo}
    , #{tlphNo}
    , NVL(#{ifType}, 'WEB')
    , SYSDATE
    , #{dclaDeedEftDt}
    , #{sbscLmtQnty}
    , #{sbscCircuitNum}
    , #{dlnqAmt}
    , #{eiccId}
)

